import React, { useState, useContext, createContext, useEffect } from 'react';
import { Search, Plus, ChevronRight, ChevronDown, Users, Clock, MessageCircle, CheckSquare, User, X, Send, AlertTriangle, Calendar } from 'lucide-react';

// Mock data
const initialData = {
  ideas: [
    {
      id: 1,
      title: "E-Ticaret Mobil Uygulaması",
      description: "Kullanıcı dostu arayüzü olan modern bir e-ticaret uygulaması geliştirmek",
      category: "Teknoloji",
      status: "Devam Ediyor",
      priority: "Yüksek",
      tags: ["mobil", "e-ticaret", "react-native"],
      createdAt: "2024-01-15",
      updatedAt: "2024-01-20",
      assignedTo: ["Ahmet Y.", "Zeynep K."],
      progress: 65,
      tasks: [
        {
          id: 101,
          title: "UI/UX Tasarım",
