      description: "Modern tasarım ve SEO optimizasyonu ile web sitesi güncellemesi",
      category: "Tasarım",
      status: "Planlanan",
      priority: "Orta",
      tags: ["web", "seo", "tasarım"],
      createdAt: "2024-01-10",
      updatedAt: "2024-01-18",
      assignedTo: ["Mehmet S."],
      progress: 25,
      tasks: [
        {
          id: 201,
          title: "SEO Analizi",
          description: "Mevcut site SEO durumu analizi",
          status: "Beklemede",
          priority: "Orta",
