        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.7)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000,
          backdropFilter: 'blur(5px)'
        }}>
          <div className="modal-content" style={{ maxWidth: '700px', width: '95%' }}>
            <div className="modal-header">
              <h2>📋 {selectedTask.title}</h2>
              <button 
                onClick={() => setIsTaskModalOpen(false)}
                style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer', fontSize: '24px' }}
              >
                <X size={24} />
              </button>
            </div>
            <div className="modal-body">
              <TaskDetailModal task={selectedTask} onClose={() => setIsTaskModalOpen(false)} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// Yeni Fikir Form Komponenti
function NewIdeaForm({ onSubmit, onCancel }) {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    category: 'Teknoloji',
    priority: 'Orta',
    assignedTo: '',
    tags: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.title.trim()) {
      onSubmit({
        ...formData,
        assignedTo: formData.assignedTo ? formData.assignedTo.split(',').map(s => s.trim()) : [],
        tags: formData.tags ? formData.tags.split(',').map(s => s.trim()) : [],
        status: 'Planlanan'
      });
      setFormData({
        title: '',
        description: '',
        category: 'Teknoloji',
        priority: 'Orta',
        assignedTo: '',
        tags: ''
      });
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="form-group">
        <label>Fikir Başlığı *</label>
        <input
          type="text"
          value={formData.title}
          onChange={(e) => setFormData({...formData, title: e.target.value})}
          placeholder="Fikrinizin başlığını yazın..."
          required
        />
      </div>

      <div className="form-group">
        <label>Açıklama</label>
        <textarea
          value={formData.description}
          onChange={(e) => setFormData({...formData, description: e.target.value})}
          placeholder="Fikrinizi detaylıca açıklayın..."
          rows={4}
        />
      </div>

      <div style={{ display: 'flex', gap: '15px' }}>
        <div className="form-group" style={{ flex: 1 }}>
          <label>Kategori</label>
          <select
            value={formData.category}
            onChange={(e) => setFormData({...formData, category: e.target.value})}
          >
            <option value="Teknoloji">Teknoloji</option>
            <option value="Tasarım">Tasarım</option>
            <option value="Pazarlama">Pazarlama</option>
            <option value="Operasyon">Operasyon</option>
            <option value="Strateji">Strateji</option>
          </select>
        </div>

        <div className="form-group" style={{ flex: 1 }}>
          <label>Öncelik</label>
          <select
            value={formData.priority}
            onChange={(e) => setFormData({...formData, priority: e.target.value})}
          >
            <option value="Düşük">Düşük</option>
            <option value="Orta">Orta</option>
            <option value="Yüksek">Yüksek</option>
          </select>
        </div>
      </div>

      <div className="form-group">
        <label>Atanacak Kişiler</label>
        <input
          type="text"
          value={formData.assignedTo}
          onChange={(e) => setFormData({...formData, assignedTo: e.target.value})}
          placeholder="Ahmet Y., Zeynep K. (virgülle ayırın)"
        />
      </div>

      <div className="form-group">
        <label>Etiketler</label>
        <input
          type="text"
          value={formData.tags}
          onChange={(e) => setFormData({...formData, tags: e.target.value})}
          placeholder="mobil, react, tasarım (virgülle ayırın)"
        />
      </div>

      <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end', marginTop: '30px' }}>
        <button type="button" onClick={onCancel} className="btn-secondary">
          İptal
        </button>
        <button type="submit" className="btn-primary">
          <Plus size={16} style={{ marginRight: '8px' }} />
          Fikir Oluştur
        </button>
      </div>
    </form>
  );
}

// Yeni Görev Form Komponenti
function NewTaskForm({ onSubmit, onCancel }) {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    priority: 'Orta',
    assignedTo: '',
    dueDate: '',
    status: 'Beklemede'
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.title.trim()) {
      onSubmit(formData);
      setFormData({
        title: '',
        description: '',
        priority: 'Orta',
        assignedTo: '',
        dueDate: '',
        status: 'Beklemede'
      });
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="form-group">
        <label>Görev Başlığı *</label>
        <input
          type="text"
          value={formData.title}
          onChange={(e) => setFormData({...formData, title: e.target.value})}
          placeholder="Görevin başlığını yazın..."
          required
        />
      </div>

      <div className="form-group">
        <label>Açıklama</label>
        <textarea
          value={formData.description}
          onChange={(e) => setFormData({...formData, description: e.target.value})}
          placeholder="Görevin detaylarını açıklayın..."
          rows={3}
        />
      </div>

      <div style={{ display: 'flex', gap: '15px' }}>
        <div className="form-group" style={{ flex: 1 }}>
          <label>Öncelik</label>
          <select
            value={formData.priority}
            onChange={(e) => setFormData({...formData, priority: e.target.value})}
          >
            <option value="Düşük">Düşük</option>
            <option value="Orta">Orta</option>
            <option value="Yüksek">Yüksek</option>
          </select>
        </div>

        <div className="form-group" style={{ flex: 1 }}>
          <label>Durum</label>
          <select
            value={formData.status}
            onChange={(e) => setFormData({...formData, status: e.target.value})}
          >
            <option value="Beklemede">Beklemede</option>
            <option value="Devam Ediyor">Devam Ediyor</option>
            <option value="Tamamlandı">Tamamlandı</option>
          </select>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '15px' }}>
        <div className="form-group" style={{ flex: 1 }}>
          <label>Atanan Kişi</label>
          <input
            type="text"
            value={formData.assignedTo}
            onChange={(e) => setFormData({...formData, assignedTo: e.target.value})}
            placeholder="Ahmet Y."
          />
        </div>

        <div className="form-group" style={{ flex: 1 }}>
          <label>Son Tarih</label>
          <input
            type="date"
            value={formData.dueDate}
            onChange={(e) => setFormData({...formData, dueDate: e.target.value})}
          />
        </div>
      </div>

      <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end', marginTop: '30px' }}>
        <button type="button" onClick={onCancel} className="btn-secondary">
          İptal
        </button>
        <button type="submit" className="btn-primary">
          <CheckSquare size={16} style={{ marginRight: '8px' }} />
          Görev Oluştur
        </button>
      </div>
    </form>
  );
}

// Görev Detay Modal Komponenti
function TaskDetailModal({ task, onClose }) {
  const [activeTab, setActiveTab] = useState('details');
  const [newComment, setNewComment] = useState('');

  const tabStyle = (isActive) => ({
    padding: '10px 20px',
    border: 'none',
    background: isActive ? 'linear-gradient(135deg, #667eea, #764ba2)' : 'transparent',
    color: isActive ? 'white' : '#666',
    borderRadius: '8px',
    cursor: 'pointer',
    transition: 'all 0.2s ease',
    fontWeight: isActive ? '600' : '400'
  });

  return (
    <div>
      {/* Tab Navigation */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '20px', borderBottom: '1px solid #eee', paddingBottom: '15px' }}>
        <button
          style={tabStyle(activeTab === 'details')}
          onClick={() => setActiveTab('details')}
        >
          📋 Detaylar
        </button>
        <button
          style={tabStyle(activeTab === 'checklist')}
          onClick={() => setActiveTab('checklist')}
        >
          ✅ Checklist ({task.checklist?.length || 0})
        </button>
        <button
          style={tabStyle(activeTab === 'comments')}
          onClick={() => setActiveTab('comments')}
        >
          💬 Yorumlar ({task.comments?.length || 0})
        </button>
      </div>

      {/* Tab Content */}
      {activeTab === 'details' && (
        <div>
          <div style={{ marginBottom: '20px' }}>
            <h4 style={{ color: '#333', marginBottom: '8px' }}>📝 Açıklama</h4>
            <p style={{ color: '#666', lineHeight: '1.6', padding: '12px', background: '#f8f9fa', borderRadius: '8px' }}>
              {task.description || 'Açıklama eklenmemiş'}
            </p>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
            <div>
              <h4 style={{ color: '#333', marginBottom: '8px' }}>👤 Atanan</h4>
              <p style={{ color: '#666' }}>{task.assignedTo}</p>
            </div>

            <div>
              <h4 style={{ color: '#333', marginBottom: '8px' }}>📅 Son Tarih</h4>
              <p style={{ color: '#666' }}>{task.dueDate}</p>
            </div>

            <div>
              <h4 style={{ color: '#333', marginBottom: '8px' }}>🔄 Durum</h4>
              <span className={`status-${task.status.toLowerCase().replace(' ', '-')}`} style={{
                background: 'rgba(102, 126, 234, 0.1)',
                color: '#667eea',
                padding: '4px 12px',
                borderRadius: '20px',
                fontSize: '12px'
              }}>
                {task.status}
              </span>
            </div>

            <div>
              <h4 style={{ color: '#333', marginBottom: '8px' }}>⚡ Öncelik</h4>
              <span className={`priority-${task.priority.toLowerCase()}`} style={{
                padding: '4px 12px',
                borderRadius: '20px',
                fontSize: '12px'
              }}>
                {task.priority}
              </span>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'checklist' && (
        <div>
          <h4 style={{ color: '#333', marginBottom: '15px' }}>✅ Görev Listesi</h4>
          {task.checklist && task.checklist.length > 0 ? (
            <div>
              {task.checklist.map(item => (
                <div key={item.id} style={{
                  display: 'flex',
                  alignItems: 'center',
                  padding: '10px',
                  background: item.completed ? '#f0f8f0' : '#f8f9fa',
                  borderRadius: '8px',
                  marginBottom: '8px',
                  border: `1px solid ${item.completed ? '#4caf50' : '#e1e5e9'}`
                }}>
                  <input
                    type="checkbox"
                    checked={item.completed}
                    readOnly
                    style={{ marginRight: '12px' }}
                  />
                  <span style={{
                    color: item.completed ? '#4caf50' : '#333',
                    textDecoration: item.completed ? 'line-through' : 'none'
                  }}>
                    {item.text}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p style={{ color: '#999', fontStyle: 'italic' }}>Henüz checklist öğesi eklenmemiş</p>
          )}
        </div>
      )}

      {activeTab === 'comments' && (
        <div>
          <h4 style={{ color: '#333', marginBottom: '15px' }}>💬 Yorumlar</h4>
          
          {task.comments && task.comments.length > 0 ? (
            <div style={{ marginBottom: '20px' }}>
              {task.comments.map(comment => (
                <div key={comment.id} style={{
                  background: '#f8f9fa',
                  borderRadius: '12px',
                  padding: '15px',
                  marginBottom: '12px',
                  borderLeft: '4px solid #667eea'
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                    <strong style={{ color: '#333' }}>{comment.author}</strong>
                    <span style={{ color: '#999', fontSize: '12px' }}>{comment.date}</span>
                  </div>
                  <p style={{ color: '#666', margin: 0, lineHeight: '1.5' }}>{comment.text}</p>
                </div>
              ))}
            </div>
          ) : (
            <p style={{ color: '#999', fontStyle: 'italic', marginBottom: '20px' }}>Henüz yorum yapılmamış</p>
          )}

          {/* Yeni Yorum Formu */}
          <div style={{ borderTop: '1px solid #eee', paddingTop: '20px' }}>
            <textarea
              placeholder="Yorumunuzu yazın..."
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              style={{
                width: '100%',
                minHeight: '80px',
                padding: '12px',
                border: '2px solid #e1e5e9',
                borderRadius: '8px',
                marginBottom: '12px',
                fontSize: '14px',
                resize: 'vertical'
              }}
            />
            <button
              style={{
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                color: 'white',
                border: 'none',
                padding: '10px 20px',
                borderRadius: '8px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '8px'
              }}
              onClick={() => {
                if (newComment.trim()) {
                  // Yorum ekleme fonksiyonu burada çağrılacak
                  setNewComment('');
                }
              }}
            >
              <Send size={16} />
              Yorum Gönder
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
